INSERT INTO email_outbox (message_key, category, to_email, to_name, user_id, subject, body_html, body_text, entity_type, entity_id, status, provider_id, error, attempts, sent_at, created_at) VALUES ('demo-new-n-6abe9451c421b8.62922630-u6', 'notification', 'emmanuel@itec.rw', 'Emmanuel Safari', (SELECT id FROM users WHERE email = 'emmanuel@itec.rw' LIMIT 1), 'Invoice issued', REPLACE(REPLACE('<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Invoice issued</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Invoice issued</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">INV-2026-0004 for USD 2,823.50 is issued and due on 2026-10-16.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;margin:18px 0;border-collapse:collapse\"><tr><td style=\"padding:7px 12px 7px 0;font-size:13px;color:#77828d;border-bottom:1px solid #e9edf1;white-space:nowrap\">Reference</td><td style=\"padding:7px 0;font-size:14px;color:#22303c;border-bottom:1px solid #e9edf1;font-weight:600\">INV-2026-0004</td></tr><tr><td style=\"padding:7px 12px 7px 0;font-size:13px;color:#77828d;border-bottom:1px solid #e9edf1;white-space:nowrap\">Area</td><td style=\"padding:7px 0;font-size:14px;color:#22303c;border-bottom:1px solid #e9edf1;font-weight:600\">Invoices</td></tr></table><p style=\"margin:24px 0 8px\"><a href=\"http://localhost/logistics-mvc/invoices\" style=\"display:inline-block;padding:11px 22px;background:#AD7D00;color:#ffffff;text-decoration:none;border-radius:6px;font-size:14px;font-weight:600\">Open it in LMS</a></p><p style=\"margin:0 0 6px;font-size:12px;color:#8a949e\">If the button does not work, open this address:<br><span style=\"color:#5b6670;word-break:break-all\">http://localhost/logistics-mvc/invoices</span></p></td></tr><tr><td style=\"padding:16px 26px;background:#f7f9fb;border-top:1px solid #e9edf1\"><p style=\"margin:0;font-size:11px;line-height:1.6;color:#8a949e\">This message was sent by the LMS logistics system on behalf of the company named above. Please do not reply to it directly.</p><p style=\"margin:6px 0 0;font-size:11px;color:#9aa4ad\">Powered by ITEC LTD &copy; 2026</p></td></tr></table></td></tr></table></body></html>', 'INV-2026-0004', '[[#lms-code-0#]]'), '[[#lms-code-0#]]', @code_invoices_4), REPLACE(REPLACE('Invoice issued\n\nINV-2026-0004 for USD 2,823.50 is issued and due on 2026-10-16.\n\nReference: INV-2026-0004\nArea: Invoices\n\nOpen it in LMS: http://localhost/logistics-mvc/invoices\n\nThis message was sent by the LMS logistics system on behalf of the company named above. Please do not reply to it directly.\nPowered by ITEC LTD (c) 2026', 'INV-2026-0004', '[[#lms-code-0#]]'), '[[#lms-code-0#]]', @code_invoices_4), 'invoices', REPLACE(REPLACE('INV-2026-0004', 'INV-2026-0004', '[[#lms-code-0#]]'), '[[#lms-code-0#]]', @code_invoices_4), 'skipped', NULL, 'Example data: recorded for show, never sent.', 3, NULL, '2026-10-01 19:11:45');
