INSERT INTO email_outbox (message_key, category, to_email, to_name, user_id, subject, body_html, body_text, entity_type, entity_id, status, provider_id, error, attempts, sent_at, created_at) VALUES ('demo-new-invoice-issued-4', 'invoice', 'imports@kigalihardware.rw', 'Jean Claude Mugabo', NULL, REPLACE(REPLACE('Invoice INV-2026-0004 from ITEC Cargo ltd', 'INV-2026-0004', '[[#lms-code-0#]]'), '[[#lms-code-0#]]', @code_invoices_4), REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE('<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Invoice INV-2026-0004 from ITEC Cargo ltd</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Invoice INV-2026-0004</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Dear Jean Claude Mugabo,</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Thank you for your business. Invoice INV-2026-0004 is set out below, covering the work carried out for Kigali Hardware Ltd. It falls due on 2026-10-16.</p><p style=\"margin:22px 0 8px;font-size:12px;letter-spacing:.8px;text-t