-- existing records the example changed
-- one 20 L drum of engine oil used on the job card
UPDATE inventory_items SET quantity = GREATEST(quantity - 1, 0), status = CASE WHEN quantity <= 0 THEN 'out_of_stock' WHEN quantity <= minimum_level THEN 'reorder' ELSE 'in_stock' END WHERE sku = 'SKU-2026-0001';
-- the odometer and next service written on the job card
UPDATE vehicles SET mileage = GREATEST(mileage, 186450), next_service_date = '2026-12-30' WHERE plate_number = 'RAD 482 K';

COMMIT;

-- Check: the new pages now have rows.
SELECT 'supplier_bills' AS page, COUNT(*) AS rows_now FROM supplier_bills UNION ALL SELECT 'supplier_payments', COUNT(*) FROM supplier_payments UNION ALL SELECT 'disbursements', COUNT(*) FROM disbursements UNION ALL SELECT 'storage_lots', COUNT(*) FROM storage_lots UNION ALL SELECT 'storage_releases (gate passes)', COUNT(*) FROM storage_releases UNION ALL SELECT 'containers', COUNT(*) FROM containers UNION ALL SELECT 'journeys', COUNT(*) FROM journeys UNION ALL SELECT 'bank_statements', COUNT(*) FROM bank_statements;
